            words["vm_perk_cooking_70_flavor"] = "Ситий воїн краще б’ється, краще копає і взагалі значно рідше ставить дурні запитання.";
            words["vm_perk_cooking_100_name"] = "МІШЛЕН ВАЛЬГАЛЛИ";
