            words["vm_perk_crafting_35_desc"] = "Під час покращення спорядження є 35% шанс не витратити ресурси. Одне натискання завантажує сировину або паливо до чверті повної місткості станції, округленої вгору й разом із першим предметом; вільне місце, ресурси гравця та сумісний тип обмежують фактичну кількість.";
            words["vm_perk_crafting_35_flavor"] = "Якщо молот ударив правильно, навіщо переводити ще одне залізо?";
            words["vm_perk_crafting_70_name"] = "Гарантія до Рагнароку";
words["vm_perk_crafting_70_desc"] = "Зведені майстром конструкції отримують +20% до діапазону структурної підтримки. Крафт може брати ресурси зі скринь гравців у тій самій мережі майстерні; тип і рівень потрібної станції лишаються ванільними.";
            words["vm_perk_crafting_70_flavor"] = "Кузня першого рівня? Для майстра це просто маленька кузня.";
            words["vm_perk_crafting_100_name"] = "Визнання Вьолундра";
            words["vm_perk_crafting_100_desc"] = "Вьолундр визнає твою майстерність і дарує прихильність. Спрямуй її через Божественне натхнення на створення Шедеврів. Майстерні ідоли, можливо, ще знайдуть місце у твоїй справі, а Кузня Потенціалу натякає на інші можливості.";
            words["vm_perk_crafting_100_desc_pending"] = "Вьолундр визнає твою майстерність. Золота майстерність готується в межах етапу 100-A; божественні дії та ідоли поки недоступні.";
            words["vm_perk_crafting_100_flavor"] = "Майстерність кується не лише залізом.";
            words["vm_perk_farming_35_name"] = "Руки пам’ятають";
            words["vm_perk_farming_35_desc"] = "Із культиватором на панелі швидкого доступу зібрана вирощена культура автоматично висаджується з витратою насіння та дає XP за посадку. Дикі культури збираються групою в радіусі 4 м; шанс бонусного ресурсу для них збільшується на 15 відсоткових пунктів.";
            words["vm_perk_farming_35_flavor"] = "Фрейя посміхнулася. Або ти просто добре смикнув моркву.";
            words["vm_perk_farming_70_name"] = "Сад без кордонів";
            words["vm_perk_farming_70_desc"] = "Посаджені майстром культури ігнорують відстань між рослинами, дах і сонячне світло, але зберігають вимоги до ґрунту й біому. Приручення тварин поруч із майстром відбувається на 50% швидше.";
            words["vm_perk_farming_70_flavor"] = "Бо нахилятися двічі — це вже бюрократія.";
            words["vm_perk_farming_100_name"] = "АГРОХОЛДИНГ ФРЕЙЇ";
            words["vm_perk_farming_100_desc"] = "Овочі, культури та дерева можна садити будь-як близько одне до одного. Вони більше не заважають одне одному рости через стандартну перевірку відстані.";
            words["vm_perk_farming_100_flavor"] = "Якщо дика береза може рости впритул до сосни, то морква якось переживе сусіда.";
            words["vm_perk_fishing_35_name"] = "Ощадливий рибалка";
            words["vm_perk_fishing_35_desc"] = "Успішний вилов нерідко повертає наживку для наступного закидання. Рибі не пощастило, зате черв’як ще побачить світанок.";
            words["vm_perk_fishing_35_flavor"] = "Риба програла. Черв’як теж якось вижив. Усі, крім риби, задоволені.";
            words["vm_perk_fishing_70_name"] = "Перша тяга";
            words["vm_perk_fishing_70_desc"] = "Після підсікання ненадовго витрачаєш значно менше витривалості на витягування риби. Тягни одразу, поки здобич не згадала, як боротися.";
            words["vm_perk_fishing_70_flavor"] = "Три секунди слави, після яких знову починається чесна боротьба людини з оселедцем.";
            words["vm_perk_fishing_100_name"] = "РИБА БІЛЬША, БО Я ТАК СКАЗАВ";
            words["vm_perk_fishing_100_desc"] = "Під час вилову є 30% шанс підвищити quality риби на +1, не вище стандартного максимуму.";
            words["vm_perk_fishing_100_flavor"] = "Якщо вона не більша за човен, це просто невдала риболовля.";
            words["vm_perk_jump_35_name"] = "Кістки ще цілі";
            words["vm_perk_jump_35_desc"] = "Безпечна висота падіння збільшується на 4 метри. Шкода від падіння починається на 4 метри пізніше.";
            words["vm_perk_jump_35_flavor"] = "Коліна скриплять, але поки що тримаються.";
            words["vm_perk_jump_70_name"] = "Другий подих";
            words["vm_perk_jump_70_desc"] = "Один раз у повітрі можна стрибнути вдруге із силою 80% від звичайного стрибка. Якщо саме шкода від падіння мала б убити, залишаєшся з 1 HP. Захист від смертельного падіння: перезарядка 5 хвилин.";
            words["vm_perk_jump_70_flavor"] = "Навіть коли земля вже близько, майстер знаходить ще один крок.";
            words["vm_perk_jump_100_name"] = "ГРАВІТАЦІЯ — ЦЕ РЕКОМЕНДАЦІЯ";
            words["vm_perk_jump_100_desc"] = "Можна виконати другий стрибок у повітрі. Другий стрибок має 80% сили звичайного та витрачає стандартну витривалість.";
            words["vm_perk_jump_100_flavor"] = "Фізика протестує. Вікінг ігнорує протест.";
            words["vm_perk_pickaxes_35_name"] = "Руда наче пір’я";
            words["vm_perk_pickaxes_35_desc"] = "Руди й інші предмети, які у звичайному світі не проходять крізь портал, крім квестових, важать на 75% менше — незалежно від поточних налаштувань порталів світу.";
            words["vm_perk_pickaxes_35_flavor"] = "Портал уперто не пускає руду. Твої плечі вже перестали сперечатися.";
            words["vm_perk_pickaxes_70_name"] = "ТОР СХВАЛЮЄ ЦЕЙ УДАР";
            words["vm_perk_pickaxes_70_desc"] = "Удар кайла інколи пошкоджує сусідні частини тієї самої жили. Зрідка могутній удар розсипає всю жилу, супроводжуваний підземним громом.";
            words["vm_perk_pickaxes_70_flavor"] = "Це вже не видобуток. Це геологічна подія.";
            words["vm_perk_pickaxes_100_name"] = "РУДА ТЕПЕР ПІНОПЛАСТ";
            words["vm_perk_pickaxes_100_desc"] = "Руди, металеві уламки та злитки важать на 75% менше для цього персонажа.";
            words["vm_perk_pickaxes_100_flavor"] = "Тридцять злитків заліза? Просто трохи важчий сніданок.";
            words["vm_perk_ride_35_name"] = "Дай звірові подихати";
            words["vm_perk_ride_35_desc"] = "Після спринту їздовий звір значно швидше повертає витривалість, доки ти не женеш його знову. Навіть бикоящур має право перевести подих.";
            words["vm_perk_ride_35_flavor"] = "Навіть локс іноді хоче п’ять секунд без твоїх геніальних наказів.";
            words["vm_perk_ride_70_name"] = "Сідло не віддам";
            words["vm_perk_ride_70_desc"] = "Поки ти в сідлі, звір легше переживає падіння, менше хитається та відлітає від ударів. Вершник і звір тримаються дороги, а не чужих побажань.";
            words["vm_perk_ride_70_flavor"] = "Звалити вікінга з сідла тепер можна переважно дипломатією.";
            words["vm_perk_ride_100_name"] = "ЛОКС НА КРУЇЗ-КОНТРОЛІ";
            words["vm_perk_ride_100_desc"] = "Під час звичайного руху, але не sprint, їздовий звір відновлює витривалість зі швидкістю 50% від нормального відновлення у спокої.";
            words["vm_perk_ride_100_flavor"] = "Ви вже не вершник і тварина. Ви одна дуже дивна транспортна система.";
            words["vm_perk_run_35_name"] = "Ритм дороги";
            words["vm_perk_run_35_desc"] = "Безперервний спринт дає рівні ритму через 3, 5 і 7 с; на максимумі швидкість зростає на 20%, а витрати витривалості на спринт падають на 40%. Ритм скидається після зупинки, вичерпання витривалості, сильного приголомшення чи недійсного руху. Якщо ворожий удар залишає менше 50% максимального здоров’я, відновлюється 35% максимальної витривалості, а швидкість зростає на 15% на 10 с. Перезарядка: 5 хв.";
            words["vm_perk_run_35_flavor"] = "Крок за кроком дорога підлаштовується під тебе. Коли сил бракує, ноги все одно не здаються.";
            words["vm_perk_run_70_name"] = "Іісус з Мідгарду";
            words["vm_perk_run_70_desc"] = "На максимальному ритмі схили, нерівна земля й мілководдя менше сповільнюють рух. У глибокій воді можна бігти поверхнею до 10 с, потім починається звичайне плавання. Перезарядка бігу по воді: 45 с після завершення.";
            words["vm_perk_run_70_flavor"] = "Коли крок знаходить свій ритм, навіть хвилі стають дорогою.";
            words["vm_perk_run_100_name"] = "ІСУС ІЗ МІДГАРДУ";
            words["vm_perk_run_100_desc"] = "Під час sprint можна бігти по поверхні води протягом перших 10 секунд. Здатність відновлюється після повернення на тверду землю.";
            words["vm_perk_run_100_flavor"] = "Човен? Човен потрібен людям, які недостатньо добре бігають.";
            words["vm_perk_sneak_35_name"] = "Тиха хода";
            words["vm_perk_sneak_35_desc"] = "Навприсядки швидкість руху зростає на 25%, а витрати витривалості на крадьку зменшуються на 30%. Твій шум і помітність для ворогів трохи знижені.";
            words["vm_perk_sneak_35_flavor"] = "Навіть ліс не шелестить зайвий раз за тим, хто знає, куди ступити.";
            words["vm_perk_sneak_70_name"] = "Під покровом";
            words["vm_perk_sneak_70_desc"] = "Після 1,5–2 с навприсядки поза прямою видимістю ворогів ти входиш у покров: здалеку тебе значно важче помітити, а вороги швидше втрачають ціль, коли гублять тебе з виду. У радіусі близько 3 м тебе можуть виявити. Атака, спринт, вставання, отримання шкоди або наближення ворога зривають покров.";
            words["vm_perk_sneak_70_flavor"] = "Тінь приховує не чаклунством, а тишею, терпінням і вчасним кроком.";
            words["vm_perk_sneak_100_name"] = "ТУТ ВЗАГАЛІ НІКОГО НЕМАЄ";
            words["vm_perk_sneak_100_desc"] = "Поки персонаж перебуває в sneak, вороги можуть вперше візуально помітити його лише майже впритул. Шум, атака та вже агресивні вороги продовжують працювати за звичайними правилами.";
            words["vm_perk_sneak_100_flavor"] = "Ти не невидимий. Просто світ чемно вдає, що тебе не існує.";
            words["vm_perk_swim_35_name"] = "Морський гарт";
            words["vm_perk_swim_35_desc"] = "Під час плавання швидкість зростає на 20%, а витрати витривалості зменшуються на 25%. Після виходу з води ефект Wet швидко скорочується до 30 секунд; він не зникає миттєво.";
            words["vm_perk_swim_35_flavor"] = "Холодна вода вже не тягне майстра вниз, а лише лишає краплі на плащі.";
            words["vm_perk_swim_70_name"] = "Сила припливу";
            words["vm_perk_swim_70_desc"] = "Швидкість плавання загалом на 40% вища за звичайну. Після 1 с майже нерухомо у воді починає відновлюватися витривалість зі швидкістю 40% від звичайної наземної; рух припиняє відновлення. Коли під час плавання витривалість падає нижче 15%, відновлюється 25% максимуму. Перезарядка резерву: 3 хв.";
            words["vm_perk_swim_70_flavor"] = "Море дає перепочинок тому, хто навчився триматися на його хвилях.";
            words["vm_perk_swim_100_name"] = "АКВАМЕН ІЗ TEMU";
            words["vm_perk_swim_100_desc"] = "Коли персонаж у воді й не дає movement input, витривалість одразу починає відновлюватися зі швидкістю 40% від нормальної. Стріляти з лука під час плавання цей перк не дозволяє.";
            words["vm_perk_swim_100_flavor"] = "Якщо море хотіло беззбройну здобич, воно вибрало не того вікінга.";
            words["vm_perk_woodcutting_35_name"] = "Один удар. Одне дерево.";
            words["vm_perk_woodcutting_35_desc"] = "Кожен удар по стоячому дереву має 20% шанс миттєво повалити його й послідовно розколоти утворені частини. Для окремої неушкодженої колоди або пенька лишається одноразовий шанс 25%.";
            words["vm_perk_woodcutting_35_flavor"] = "Лісоруби сперечаються про техніку. Ти просто б’єш сильніше.";
            words["vm_perk_woodcutting_70_name"] = "Дерево? Яке дерево?";
            words["vm_perk_woodcutting_70_desc"] = "Деревина складається до 100 одиниць у твоєму інвентарі, поки вивчений цей перк; у скриню переноситься до 50 за раз. Звичайна деревина важить лише 10% початкової ваги, інша деревина — 50%. Бонусна цінна деревина залежить від рівня навички, а не від цього перка.";
            words["vm_perk_woodcutting_70_flavor"] = "Нести половину лісу легше, якщо достатньо довго переконувати себе, що це просто гілочки.";
            words["vm_perk_woodcutting_100_name"] = "ЛІС ВИРІШИВ БИТИСЯ";
            words["vm_perk_woodcutting_100_desc"] = "Повалені цим персонажем дерева та колоди отримують збільшену силу руху та завдають ×5 шкоди при зіткненні з іншими деревами, істотами та іншими допустимими цілями. Персонаж також отримує 50% опору шкоді від дерев і деревоподібних істот, зокрема сімейства Greydwarf, Abomination та інших налаштованих деревних ворогів.";
            words["vm_perk_woodcutting_100_flavor"] = "Ти більше не рубаєш ліс. Ти вербуєш його.";
            words["vm_perk_swords_35_name"] = "Швидше за думку";
            words["vm_perk_swords_35_desc"] = "Удари мечем завдають на 25% більше шкоди ворогам, які втратили рівновагу. Темп спецатаки на 20% вищий за штатний, зі збереженням її фаз замаху й відновлення. Вона завдає ×1,35 шкоди та ×1,75 шкоди рівновазі, витрачаючи звичайну кількість витривалості. Звичайна атака не змінюється.";
            words["vm_perk_swords_35_flavor"] = "Ворог відкрився. Було б неввічливо не скористатися.";
            words["vm_perk_swords_70_name"] = "Наступ — це захист";
            words["vm_perk_swords_70_desc"] = "Якщо почати атаку мечем за мить до ворожого удару ближнього бою, удар буде парирувано без переривання твоєї атаки. Продовжений удар отримує +50% до шкоди рівновазі.";
            words["vm_perk_swords_70_flavor"] = "Найкращий блок — клинок, який уже летить назустріч.";
            words["vm_perk_swords_100_name"] = "Мить між ударами";
            words["vm_perk_swords_100_desc"] = "Якщо атакою меча влучити в коротке timing-window атаки ворога, його удар автоматично парирується, а stamina, витрачена на твій удар, повертається.";
            words["vm_perk_swords_100_flavor"] = "Майстер не блокує удар. Він просто опиняється в правильній миті раніше за ворога.";
            words["vm_perk_axes_35_name"] = "Chop-chop";
            words["vm_perk_axes_35_desc"] = "Кожне попадання сокирою накладає до 3 зарубок на ціль: кожна збільшує отриману різальну шкоду на 11% протягом 180 с. Зарубки відкривають перевірки готовності до КАТА з перка 70 рівня. Спецатака прискорюється разом із навичкою сокир, до +50% на 100 рівні.";
            words["vm_perk_axes_35_flavor"] = "Якщо вони стали поруч — це вже їхня помилка.";
            words["vm_perk_axes_70_name"] = "КАТ";
words["vm_perk_axes_70_desc"] = "Кожні 2.5 с ціль із зарубками може стати готовою до КАТА на 7 с: шанс 8.3% / 16.7% / 25% за 1 / 2 / 3 зарубки. На малих ворогах перевірка діє при будь-якому запасі здоров’я. Справжня спецатака страчує ціль, лікує на 25% її здоров’я перед стратою та дає +25% різальної шкоди на 10 с. Перезарядка КАТА: 15 с.";
            words["vm_perk_axes_70_flavor"] = "Сокира не питає, скільки в тебе ще здоров’я. Вона просто перевіряє, чи вже досить.";
            words["vm_perk_axes_100_name"] = "Вирок сокири";
            words["vm_perk_axes_100_desc"] = "Спеціальна атака сокири отримує ×2 шкоди та приблизно ×2 ефективний hitbox.";
            words["vm_perk_axes_100_flavor"] = "На 70 рівні ти був катом. На 100 вирок уже виконує сама сокира.";
            words["vm_perk_clubs_35_name"] = "Дзвін у голові";
#if MASTERY_CLUBS35_EXPERIMENT
            words["vm_perk_clubs_35_name"] = "Вага переконання";
            words["vm_perk_clubs_35_desc"] = "Силовий удар булави, що добиває малого ворога, жбурляє тіло в наступного супротивника. Удар молота залишає в землі слабше відлуння.";
#else
            words["vm_perk_clubs_35_desc"] = "Удар blunt-зброєю по ворогу, який саме атакує, завдає посиленої stagger-шкоди. Сила залежить від небезпеки цілі.";
#endif
            words["vm_perk_clubs_35_flavor"] = "Десь усередині шолома ворога починає дзвонити маленький дзвін.";
            words["vm_perk_clubs_70_name"] = "Болить у всіх";
#if MASTERY_CLUBS70_EXPERIMENT
            words["vm_perk_clubs_70_name"] = "Стримана міць";
            words["vm_perk_clubs_70_desc"] = "Затисни блок із булавою чи молотом, накопичуючи заряд. Сильний удар булави отримує більше шкоди й відкидання, а добитий малий ворог летить швидше та завдає значно більше шкоди при зіткненні; ехо булави немає. Повний заряд молота залишає два слабші ехо з інтервалом 1,25 с.";
#else
            words["vm_perk_clubs_70_desc"] = "Спецатака булави створює AOE радіусом 4 м зі звичайною шкодою булави та ×3 stagger damage. Уже застанені вороги отримують ×2 крит, відлітають від удару й запускають звук виплавленого металу.";
#endif
            words["vm_perk_clubs_70_flavor"] = "Один отримав по голові — подумали всі.";
            words["vm_perk_clubs_100_name"] = "ТОР В ОРЕНДУ";
            words["vm_perk_clubs_100_desc"] = "Кожен удар club-зброєю має 20% шанс стати громовим: ×2 шкоди, великий knockback і ланцюгова блискавка по найближчих ворогах.";
            words["vm_perk_clubs_100_flavor"] = "Мйольнір зайнятий. Доведеться працювати тим, що є.";
            words["vm_perk_knives_35_name"] = "Крок убивці";
            words["vm_perk_knives_35_desc"] = "У sneak з ножем secondary-атака по ворогу в прицілі на відстані до 20 м переносить тебе за його спину. Анімація виконується на 75% швидше, а через 0.3 с зафіксована найближча ціль гарантовано отримує один shadow-hit зі шкодою special attack незалежно від руху чи рельєфу. Перезарядка: 12 секунд; вбивство скорочує залишок до 30%.";
            words["vm_perk_knives_35_flavor"] = "Коли помітили — тебе вже немає.";
            words["vm_perk_knives_70_name"] = "Тіньовий удар";
            words["vm_perk_knives_70_desc"] = "Кожне справжнє влучання ножем має 35% шанс викликати тіньовий удар, що завдає 50% шкоди без відкидання й приголомшення. Кожна тінь незалежно має 35% шанс повторити удар по цій цілі та 35% шанс перейти на іншого ворога в радіусі 10 м. Ланцюг обмежений захистом від нескінченних повторів.";
            words["vm_perk_knives_70_flavor"] = "Один клинок відкидає більше ніж одну тінь.";
            words["vm_perk_knives_100_name"] = "Друга тінь";
            words["vm_perk_knives_100_desc"] = "Кожне попадання ножем має 33% шанс завдати додатковий тіньовий удар без анімації гравця. Тіньовий удар теж має 33% шанс породити наступний. Для захисту від технічної нескінченності допускається високий hard-cap поколінь, який практично недосяжний у звичайній грі.";
            words["vm_perk_knives_100_flavor"] = "Ти вдарив один раз. Чому ворог отримав п’ять ударів — питання вже до Гель.";
#if MASTERY_SPEAR35_EXPERIMENT
            words["vm_perk_spears_35_name"] = "Нитка мисливця";
            words["vm_perk_spears_35_flavor"] = "Шукати спис у болоті — справа для тих, хто забув прив’язати мотузку.";
#elif MASTERY_RELEASE_SAFE
            words["vm_perk_spears_35_name"] = "Майже Гунгнір";
            words["vm_perk_spears_35_desc"] = "Кинутий спис летить удвічі швидше, завдає подвійної шкоди та значно менше падає по траєкторії.";
            words["vm_perk_spears_35_flavor"] = "Один ще не схвалив назву, але спис уже старається.";
#else
            words["vm_perk_spears_35_name"] = "Нитка мисливця";
            words["vm_perk_spears_35_flavor"] = "Нитка ще на верстаті.";
#endif
#if MASTERY_SPEAR35_EXPERIMENT && MASTERY_SPEAR70_EXPERIMENT
            words["vm_perk_spears_70_name"] = "Здобич на гаку";
            words["vm_perk_spears_70_flavor"] = "Гак підтягує малих. Проти велетня доводиться йти самому — і сподіватися, що спис дістане.";
#elif MASTERY_RELEASE_SAFE && !MASTERY_SPEAR35_EXPERIMENT
            words["vm_perk_spears_70_name"] = "Наступний!";
            words["vm_perk_spears_70_flavor"] = "Вони стали в лінію. Ти просто поважаєш порядок.";
#else
            words["vm_perk_spears_70_name"] = "Здобич на гаку";
            words["vm_perk_spears_70_desc"] = "Кинутий спис чіпляється за ворога. Спеціальна атака з вільною рукою притягує малого ворога до тебе, а до важкого чи боса — тебе самого; стусан вимкнений, поки нитка ціла. Дивитися на ціль не потрібно. Швидкість зростає до +100% на 100 рівні. Перешкода зупиняє рух, але не рве нитку: зміни позицію та натисни ще раз. Невдалий рух не витрачає перезарядку; успішний — 12 с. Нитка зникає при поверненні чи втраті списа, смерті цілі/гравця або телепорті. Блок повертає той самий спис.";
            words["vm_perk_spears_70_flavor"] = "Спершу треба навчити спис повертатися.";
#endif
            words["vm_perk_spears_100_name"] = "Повернись, я передумав";
            words["vm_perk_spears_100_desc"] = "Після влучання або зупинки кинутий спис повертається до власника.";
            words["vm_perk_spears_100_flavor"] = "Бігати за списом по болоту — заняття для тих, хто ще не дійшов до 100.";
            words["vm_perk_polearms_35_name"] = "Гостре розуміння";
            words["vm_perk_polearms_35_desc"] = "Якщо ідеальне парирування застаґерило ворога, автоматично виконується одна справжня кругова спецатака зі швидкістю ×1.5 і половинною витратою stamina. Без стагера автоатаки немає.";
            words["vm_perk_polearms_35_flavor"] = "Після достатньої кількості годин з алебардою навіть кухонний ніж починає поводитися серйозніше.";
            words["vm_perk_polearms_70_name"] = "М’ясорубка";
            words["vm_perk_polearms_70_desc"] = "Утримування secondary attack після першого удару переходить у програмний безперервний вихор. Кожен повний оберт завдає AoE-шкоду всім ворогам у радіусі: 35% стандартної шкоди й стагеру, 30% базової витривалості. За оберт додається стак: +40% швидкості та +20% радіусу, максимум 5.";
            words["vm_perk_polearms_70_flavor"] = "Винахідник цієї техніки явно не любив особистий простір.";
            words["vm_perk_polearms_100_name"] = "Воля Всеотця";
            words["vm_perk_polearms_100_desc"] = "Всеотець побачив у твоєму вихорі волю, здатну змінити хід битви. Лише під час безперервного обертання атгейра відбиваєш назад ворожі стріли та інші підтримувані снаряди.";
            words["vm_perk_polearms_100_flavor"] = "Ворожий постріл не має останнього слова.";
            words["vm_perk_bows_35_name"] = "Очі Хугінна";
            words["vm_perk_bows_35_desc"] = "Під час натягування лука найближча до прицілу ціль отримує золоту слабку зону. Влучання точно в неї завдає ×2 шкоди.";
            words["vm_perk_bows_35_flavor"] = "Нідавеллір назвав би це економікою. Ти називаєш це “не хочу знову крафтити”.";
            words["vm_perk_bows_70_name"] = "Навиліт";
            words["vm_perk_bows_70_desc"] = "Потримай повністю натягнутий лук до сигналу готовності: посилена стріла б’є сильніше, летить швидше й пробиває ворогів. Влучання у слабку зону береже її силу, а хвиля за ціллю відкидає наступних.";
            words["vm_perk_bows_70_flavor"] = "Хугінн бачить усе. Тепер ти теж, але тільки коли не смикаєш мишкою.";
            words["vm_perk_bows_100_name"] = "Дощ без хмар";
            words["vm_perk_bows_100_desc"] = "Кожна випущена стріла має 50% шанс породити додаткову стрілу з 70% шкоди. Додаткова стріла теж може породити наступну.";
            words["vm_perk_bows_100_flavor"] = "Ти випустив одну стрілу. Ліс почув іншу версію подій.";
            words["vm_perk_crossbows_35_name"] = "Залізна витримка";
            words["vm_perk_crossbows_35_desc"] = "Під час активної перезарядки арбалета: +20 броні, +40% поточної броні та подвоєна межа оглушення. Захист зникає після завершення або переривання перезарядки. Арбалет зберігає 85% штатного внеску навички у шкоду, а не 85% кінцевої шкоди.";
            words["vm_perk_crossbows_35_flavor"] = "Важкий постріл винагороджує того, хто пережив його підготовку.";
            words["vm_perk_crossbows_70_name"] = "Особиста польова турель";
            words["vm_perk_crossbows_70_desc"] = "Вторинна атака з арбалетом встановлює одну особисту турель. Поклади свій арбалет і стільки сумісних болтів, скільки вміститься в контейнер. Порожні руки + вторинна атака — запуск або зупинка. Турель шукає ворожих істот у передньому секторі стрільби, поки власник живий і в мережі; не атакує гравців чи приручених. Забери ту саму зброю й решту болтів із зупиненого контейнера, потім прибери порожню платформу.";
            words["vm_perk_crossbows_70_flavor"] = "Облогова машина починається зі зброї, яку варто встановити.";
            words["vm_perk_crossbows_100_name"] = "Другий постріл";
            words["vm_perk_crossbows_100_desc"] = "Після пострілу є 40% шанс, що арбалет залишиться зарядженим і наступний постріл можна буде зробити без перезарядки.";
            words["vm_perk_crossbows_100_flavor"] = "Найкраща частина перезарядки — коли її немає.";
            words["vm_perk_fists_35_name"] = "Руки розігрілись";
            words["vm_perk_fists_35_desc"] = "Послідовні влучання голими руками дають +15% швидкості атаки за стак (до +45%), а кулачною зброєю — +10% (до +30%); пауза понад 3 секунди без влучання скидає стаки. Навичка без зброї також посилює удари й масштабує шкоду, stagger та відкидання удару ногою; на 100 рівні удар ногою має +300% шкоди й +200% сили відкидання. Пасивне отримання адреналіну зростає разом із навичкою — до +150% на 100 рівні.";
            words["vm_perk_fists_35_flavor"] = "У якийсь момент ти перестаєш битися руками й починаєш вести дуже переконливу дискусію.";
            words["vm_perk_fists_70_name"] = "Хижий розгром";
            words["vm_perk_fists_70_desc"] = "Парирування голими руками отримує +10 до ванільного множника, а кулачною зброєю — +6. Реальні удари по важким ворогам і босам наповнюють окрему шкалу ЦУП; отримана від цієї цілі шкода зменшує її. На 100% наведи приціл на ціль і натисни спецатаку, щоб запустити ЦУП. Без готової захопленої цілі спецатака залишається звичайним ударом ногою. Перезарядка: 5 хвилин; кожен реальний удар кулаками скорочує її на 5 секунд.";
            words["vm_perk_fists_70_flavor"] = "Не двобій. Полювання на того, хто вважав себе завеликим для твоїх рук.";
            words["vm_perk_fists_100_name"] = "Клятва Тюра";
            words["vm_perk_fists_100_desc"] = "Тюр шанує волю, що не ламається під ударами. Його визнання дозволяє носити два сумісні трінкети одночасно: коли спільна шкала адреналіну наповнюється, обидва активуються разом.";
            words["vm_perk_fists_100_flavor"] = "Два дари. Одна непорушна клятва.";
#if MASTERY_SHIELD35_EXPERIMENT
            words["vm_perk_blocking_35_name"] = "Не за цією адресою";
            words["vm_perk_blocking_35_desc"] = "Точне парирування повертає справжній снаряд чи його стихійну силу нападнику без бонусної шкоди. Великий щит при міцному блоці зменшує stagger снаряда та гасить його статус. Не діє на постійні хмари й небезпеки землі.";
#else
            words["vm_perk_blocking_35_name"] = "Тиск у відповідь";
            words["vm_perk_blocking_35_desc"] = "Успішні блоки протягом 3 секунд накопичують тиск. Точне парирування витрачає тиск, завдає цілі додаткового stagger-удару та додає адреналін. Чим ближче block stagger до межі, тим сильніший ефект.";
#endif
            words["vm_perk_blocking_35_flavor"] = "Чим краще тебе б’ють, тим більше сил з’являється сперечатися.";
            words["vm_perk_blocking_70_name"] = "Стіна щитів";
#if MASTERY_SHIELD_RUSH_EXPERIMENT
            words["vm_perk_blocking_70_name"] = "Натиск щита";
#endif
#if MASTERY_SHIELD_RUSH_EXPERIMENT
            words["vm_perk_blocking_70_desc"] = "Затисни блок і натисни ухил, щоб рушити щитом крізь натовп без прямої шкоди й невразливості. Круглий щит чи баклер несе далі; великий відштовхує ширше й сильніше. Власне приголомшення посилює натиск.";
#else
            words["vm_perk_blocking_70_desc"] = "Працює лише зі щитом. Звичайний block повертає 5% заблокованої шкоди. Perfect parry снаряда повертає його зі 100% шкоди та +50% швидкості. Melee parry раз на 30 секунд повертає 50% шкоди нападнику й до трьох ворогів поруч.";
#endif
            words["vm_perk_blocking_70_flavor"] = "Щит перестає бути предметом. Тепер це архітектура.";
            words["vm_perk_blocking_100_name"] = "Суд Дзеркала";
            words["vm_perk_blocking_100_desc"] = "Звичайний block повертає атакуючому 15% заблокованої шкоди. Parry повертає 50%. Відбита шкода не може повторно відбиватися.";
            words["vm_perk_blocking_100_flavor"] = "Ворог нарешті отримує можливість особисто оцінити якість власної атаки.";
            words["vm_perk_dodge_35_name"] = "Не тут";
            words["vm_perk_dodge_35_desc"] = "Коли атака проходить крізь вікно невразливості перекату, ідеальне ухилення додає 25% до поточної горизонтальної швидкості й 0,1 с невразливості. Звичайний перекат без ворожого удару не активує перк.";
            words["vm_perk_dodge_35_flavor"] = "Ворог ударив точно туди, де ти дуже вдало перестав бути.";
            words["vm_perk_dodge_70_name"] = "Не цього разу";
            words["vm_perk_dodge_70_desc"] = "Справжнє ідеальне ухилення повертає половину витривалості, витраченої на перекат. Ефект спрацьовує не частіше ніж раз на 8 секунд.";
            words["vm_perk_dodge_70_flavor"] = "Цього разу — ні.";
            words["vm_perk_dodge_100_name"] = "Світ промахнувся";
            words["vm_perk_dodge_100_desc"] = "Кожен звичайний вхідний damage event має 20% шанс повністю не завдати шкоди. Працює на атаки, магію, DoT, падіння, стихійний та інший damage. Не застосовується до свідомої ціни здібностей на кшталт health sacrifice.";
            words["vm_perk_dodge_100_flavor"] = "Іноді світ просто промахується.";
            words["vm_perk_elementalmagic_35_name"] = "Шлях двох стихій";
            words["vm_perk_elementalmagic_35_desc"] = "Вогняний посох накопичує жар: довше заряджання посилює полум’я, вибух і горіння. Крижаний посох залишає морозний слід, який ранить і сповільнює ворогів. Обморожена летюча здобич опускається до землі й залишається внизу, поки діє холод; боси не підкоряються.";
            words["vm_perk_elementalmagic_35_flavor"] = "Навіть зима має лише одну вимогу: не стій на місці.";
            words["vm_perk_elementalmagic_70_name"] = "Закляття Дев’яти світів";
            words["vm_perk_elementalmagic_70_desc"] = "Вогняний посох прикликає Жарика — вогняного супутника, який б’ється на твоєму боці. Сильніший посох підсилює його; новий поклик повертає й лікує того самого живого Жарика. Крижаний посох здіймає бурю, що ранить і сковує ворогів; новий поклик переносить її.";
            words["vm_perk_elementalmagic_70_flavor"] = "Звичайний помах будить іскру; особливий наказ пробуджує стихію.";
            words["vm_perk_elementalmagic_100_name"] = "Відлуння Дев’яти світів";
            words["vm_perk_elementalmagic_100_desc"] = "Кожен offensive cast має 35% шанс безкоштовно створити ще одну копію заклинання приблизно з 75% сили. Копія теж може прокнути наступну копію. Для технічного захисту допускається високий hard-cap поколінь.";
            words["vm_perk_elementalmagic_100_flavor"] = "Ти сказав магії “досить”. Дев’ять світів відповіли хором.";
            words["vm_perk_bloodmagic_35_name"] = "Мерці не відстають";
            words["vm_perk_bloodmagic_35_desc"] = "Кістяний посох збирає навколо тебе свиту скелетів. Посох захисту підтримує життя носія щита й дозволяє підживлювати ще цілі щити власною кров’ю. Кожна наступна секунда підживлення забирає більше здоров’я.";
            words["vm_perk_bloodmagic_35_flavor"] = "Добрий супутник не запізнюється. Особливо коли йому вже нікуди поспішати.";
            words["vm_perk_bloodmagic_70_name"] = "Моя мертва свита";
            words["vm_perk_bloodmagic_70_desc"] = "Кістяний посох прикликає Торбу — живучого носія портальних речей, який уникає бою й відновлюється в безпеці. Посох захисту замикає ворога в кривавій клітці; коли пута лускають, сила щита карає бранця.";
            words["vm_perk_bloodmagic_70_flavor"] = "Скелет, який пережив три біоми й два портали, уже фактично член родини.";
            words["vm_perk_bloodmagic_100_name"] = "HR-відділ Гель";
            words["vm_perk_bloodmagic_100_desc"] = "Коли персонаж або його summon вбиває небоса, є 25% шанс підняти його тіньову копію як тимчасового союзника. Тінь живе близько 30 секунд, має зменшені HP і шкоду, не дає loot, а після смерті або завершення часу вибухає blood nova. Одночасно може існувати до 3 таких тіней. Їхні атаки та вибухи дають Blood Magic XP.";
            words["vm_perk_bloodmagic_100_flavor"] = "Гель не дала тобі армію. Ти просто почав наймати її персонал без погодження.";
        }
    }
}


